// Desempacota a lista data.jobs das buscas da RapidAPI JSearch
const vagas = [];
for (const item of $input.all()) {
  const lista = item.json?.data?.jobs || item.json?.jobs || [];
  for (const vaga of lista) {
    vaga.tipo_fonte = 'VAGAS';
    vagas.push({ json: vaga });
  }
}
return vagas;

// Normaliza os posts do feed do LinkedIn para a estrutura padrao de vagas
const resultados = [];

for (const item of $input.all()) {
  const p = item.json;
  if (!p || (!p.postId && !p.text)) continue;

  const lines = (p.text || '').split('\n').map(l => l.replace(/[\\`\*\_#]/g, ' ').trim()).filter(l => l.length > 0);
  let titulo = lines[0] || 'Oportunidade em TI no LinkedIn';
  if (titulo.length > 80) titulo = titulo.slice(0, 77) + '...';

  const author = p.authorName ? p.authorName.replace(/[\\`\*\_]/g, ' ').trim() : 'Recrutador Tech (LinkedIn)';

  let postUrl = p.url || '';
  if (!postUrl.startsWith('http')) {
    postUrl = 'https://www.linkedin.com/feed/';
  }

  resultados.push({
    json: {
      job_id: 'li_' + (p.postId || p.url),
      job_title: titulo,
      employer_name: author + ' (LinkedIn)',
      job_apply_link: postUrl,
      job_description: p.text || '',
      job_posted_at_datetime_utc: p.postedAtISO || p.scrapedAt || new Date().toISOString(),
      job_is_remote: /remoto|home\s*office|100%\s*remoto/i.test(p.text || ''),
      job_city: /feira\s*de\s*santana/i.test(p.text || '') ? 'Feira de Santana' : '',
      job_state: /feira\s*de\s*santana/i.test(p.text || '') ? 'BA' : '',
      job_location: /feira\s*de\s*santana/i.test(p.text || '') ? 'Feira de Santana, BA' : 'Brasil',
      tipo_fonte: 'POST',
      origem: 'Post no LinkedIn'
    }
  });
}

return resultados;

// Memoria de deduplicacao dupla: ID unico e Impressao Digital Semantica
// Match Score por Tecnologias e Filtro Anti-Falso Junior e Anti-Vagas Fantasmas
const staticData = $getWorkflowStaticData('global');
staticData.seenJobIds = staticData.seenJobIds || [];
staticData.seenFingerprints = staticData.seenFingerprints || [];

function normalizar(texto) {
  if (!texto) return '';
  return texto
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function gerarFingerprint(job) {
  const rawTitle = normalizar(job.job_title || '');
  const rawEmpresa = normalizar(job.employer_name || '');

  const stopWords = /\b(vaga|vagas|oportunidade|estagio|estagiario|estagiaria|junior|jr|pleno|senior|remoto|home\s*office|hibrido|presencial|brasil|sao\s*paulo|sp|feira\s*de\s*santana|ba|rj|clt|pj|efetivo)\b/g;

  let titleClean = rawTitle
    .replace(stopWords, '')
    .replace(/\b\d+\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  let empresaClean = rawEmpresa
    .replace(/\b(ltda|sa|s\s*a|inc|corp|brasil|linkedin|divulga\s*vagas|gupy|catho|infojobs|indeed|confidencial)\b/g, '')
    .replace(/\s+/g, ' ')
    .trim();

  if (titleClean.length >= 4 && empresaClean.length >= 3) {
    return 't:' + titleClean + '#e:' + empresaClean;
  }

  const descClean = normalizar(job.job_description || '').slice(0, 60);
  return 't:' + titleClean + '#d:' + descClean;
}

const resultado = [];

for (const item of $input.all()) {
  const job = item.json;
  const id = job.job_id;
  const fp = gerarFingerprint(job);

  // 1. Deteccao de duplicadas (ID ou Fingerprint)
  if ((id && staticData.seenJobIds.includes(id)) || (fp && staticData.seenFingerprints.includes(fp))) {
    continue;
  }

  // 2. Calculo e Filtro de Idade da Vaga (max 7 dias)
  let diasAtras = 0;
  if (job.job_posted_at_datetime_utc) {
    const postDate = new Date(job.job_posted_at_datetime_utc);
    const agora = new Date();
    diasAtras = Math.floor((agora - postDate) / (1000 * 60 * 60 * 24));
  }

  if (diasAtras > 7) {
    continue;
  }

  if (job.job_posted_at_datetime_utc) {
    const d = new Date(job.job_posted_at_datetime_utc);
    const dia = String(d.getUTCDate()).padStart(2, '0');
    const mes = String(d.getUTCMonth() + 1).padStart(2, '0');
    const ano = d.getUTCFullYear();
    job.data_formatada = `${dia}/${mes}/${ano}`;
  } else {
    job.data_formatada = 'Recente';
  }

  if (diasAtras === 0) {
    job.status_data = 'Publicada hoje';
  } else if (diasAtras === 1) {
    job.status_data = 'Publicada ontem';
  } else {
    job.status_data = `Publicada ha ${diasAtras} dias`;
  }

  const title = (job.job_title || '').toLowerCase();
  const desc = (job.job_description || '').toLowerCase();
  const rawEmpresa = (job.employer_name || '').trim().toLowerCase();
  const textoGeral = (title + ' ' + desc).toLowerCase();
  const city = (job.job_city || '').toLowerCase();
  const location = (job.job_location || '').toLowerCase();

  // 3. Filtro Rigoroso Anti-Vagas Fantasmas (Ghost Jobs)
  const isBanco = /\b(?:banco\s*de\s*talentos?|cadastro\s*(?:de\s*)?reserva|pool\s*de\s*talentos?|futuras?\s*oportunidades?|oportunidades?\s*futuras?|deixe\s*seu\s*curriculo|curriculo\s*no\s*banco|banco\s*de\s*curriculos?)\b/i.test(title) ||
    /\b(?:este\s*e\s*um\s*banco\s*de\s*talentos|esta\s*e\s*uma\s*vaga\s*para\s*banco\s*de\s*talentos|para\s*compor\s*nosso\s*banco\s*de\s*talentos|cadastre-?se\s*em\s*nosso\s*banco\s*de\s*talentos|apenas\s*para\s*cadastro\s*de\s*reserva)\b/i.test(desc);

  const isConfidencial = /\b(?:empresa\s*confidencial|cliente\s*confidencial|^confidencial$|^sigiloso$)\b/i.test(rawEmpresa);

  const isIscaLinkedIn = /\b(?:comente\s*["']?(?:eu\s*quero|quero|interesse|interessado)["']?|deixe\s*(?:o\s*)?seu\s*e-?mail|digite\s*["']?(?:eu\s*quero|quero)["']?|curta\s*e\s*comente|comente\s*para\s*receber|envie\s*uma\s*mensagem\s*no\s*privado\s*para\s*receber\s*o\s*link|siga\s*(?:meu|nosso)\s*perfil\s*para\s*receber|mande\s*conexao\s*para\s*receber)\b/i.test(desc);

  const isCurso = /\b(?:adquira\s*o\s*(?:curso|treinamento)|treinamento\s*obrigatorio\s*pago|taxa\s*de\s*inscricao|pague\s*a\s*taxa|matricula\s*no\s*curso|comprar\s*o\s*material)\b/i.test(desc);

  const isDescricaoVazia = (job.job_description || '').trim().length < 80;

  if (isBanco || isConfidencial || isIscaLinkedIn || isCurso || isDescricaoVazia) {
    continue;
  }

  // 4. Garantia de Link Valido para o Botao do Telegram
  if (!job.job_apply_link || typeof job.job_apply_link !== 'string' || !job.job_apply_link.startsWith('http')) {
    if (job.tipo_fonte === 'POST') {
      job.job_apply_link = 'https://www.linkedin.com/feed/';
    } else {
      job.job_apply_link = 'https://www.google.com/search?q=' + encodeURIComponent((job.job_title || '') + ' ' + (job.employer_name || ''));
    }
  }

  // 5. Analise de Match Score Ampliado para toda a Area de TI
  const stackDefs = [
    { nome: 'Python', regex: /\b(python|django|fastapi|flask)\b/i, principal: true },
    { nome: 'JavaScript', regex: /\b(javascript|js|es6)\b/i, principal: true },
    { nome: 'TypeScript', regex: /\b(typescript|ts)\b/i, principal: true },
    { nome: 'React', regex: /\b(react|reactjs|react\.js|react\s*native)\b/i, principal: true },
    { nome: 'Node.js', regex: /\b(node|nodejs|node\.js|express|nest|nestjs)\b/i, principal: true },
    { nome: 'SQL/Dados', regex: /\b(sql|mysql|postgresql|postgres|sqlite|database|banco\s*de\s*dados|power\s*bi|bi|analytics)\b/i, principal: true },
    { nome: 'Docker/DevOps', regex: /\b(docker|containers?|cloud|aws|azure)\b/i, principal: true },
    { nome: 'Git', regex: /\b(git|github|gitlab)\b/i, principal: true },
    { nome: 'Linux/Redes', regex: /\b(linux|ubuntu|redes|tcp\/ip|dns|hardware|suporte|help\s*desk)\b/i, principal: false },
    { nome: 'API REST', regex: /\b(rest|restful|apis?)\b/i, principal: false },
    { nome: 'Automacao/QA', regex: /\b(automacao|rpa|selenium|cypress|qa|testes?)\b/i, principal: false },
    { nome: 'Seguranca', regex: /\b(seguranca|cyber|soc|firewall|lgpd)\b/i, principal: false },
    { nome: 'HTML/CSS', regex: /\b(html|css|tailwind|bootstrap)\b/i, principal: false },
    { nome: 'Java', regex: /\b(java|spring|springboot)\b/i, principal: false },
    { nome: 'C#/.NET', regex: /\b(c#|\.net|dotnet)\b/i, principal: false },
    { nome: 'PHP', regex: /\b(php|laravel)\b/i, principal: false }
  ];

  const stacksEncontradas = [];
  let pontuacaoPrincipal = 0;

  for (const s of stackDefs) {
    if (s.regex.test(textoGeral)) {
      stacksEncontradas.push(s.nome);
      if (s.principal) {
        pontuacaoPrincipal++;
      }
    }
  }

  let nivelScore = 'GERAL';
  if (pontuacaoPrincipal >= 3) {
    nivelScore = 'ALTA';
  } else if (pontuacaoPrincipal >= 1) {
    nivelScore = 'MEDIA';
  }

  const stacksFormatadas = stacksEncontradas.length > 0 ? stacksEncontradas.join(', ') : 'Geral TI';
  job.match_score = nivelScore;
  job.compatibilidade_texto = `${nivelScore} (${stacksFormatadas})`;

  // 6. Filtro Anti-Falso Junior (Opcao B: Alerta em destaque)
  const expAbusivaRegex = /\b(?:experiencia\s*(?:comprovada|solida|minima)?\s*(?:de\s*)?([3-9]|\d{2,})\s*(?:anos?|yrs?|years?)|([3-9]|\d{2,})\s*(?:anos?|yrs?|years?)\s*(?:de\s*)?(?:experiencia|atuacao|pratica|vivencia)|(?:minimo|ao\s*menos|a\s*partir)\s*de\s*([3-9]|\d{2,})\s*(?:anos?))\b/i;
  const nivelPlenoSenior = /\b(?:nivel\s*pleno|nivel\s*senior|experiencia\s*senior|tech\s*lead|lideranca\s*tecnica)\b/i;

  if (expAbusivaRegex.test(desc) || nivelPlenoSenior.test(desc)) {
    job.alerta_experiencia = '[ALERTA: Exige experiencia avancada (3+ anos/pleno)]';
    job.alerta_formatado = '[ALERTA: Exige experiencia avancada (3+ anos/pleno)]\n';
  } else {
    job.alerta_experiencia = '';
    job.alerta_formatado = '';
  }

  job.botao_texto = (job.tipo_fonte === 'POST') ? 'Ver Post no LinkedIn' : 'Acessar Vaga';

  // 7. Roteamento Geografico e Categoria Profissional
  const isFeira = /feira\s*de\s*santana|fsa/.test(city) ||
                  /feira\s*de\s*santana|fsa/.test(location) ||
                  /feira\s*de\s*santana/.test(desc);

  const isRemote = job.job_is_remote === true || 
                   /remoto|home\s*office/i.test(title) ||
                   /100%\s*remoto|trabalho\s*remoto/i.test(desc);

  if (isFeira) {
    job.categoria = 'ti_fsa';
    if (id) staticData.seenJobIds.push(id);
    if (fp) staticData.seenFingerprints.push(fp);
    resultado.push(item);
    continue;
  }

  if (isRemote) {
    const isDev = /desenvolvedor|developer|dev|frontend|backend|fullstack|software|web|programador|react|node|python|java|javascript|low\s*code|c#|angular/i.test(title) ||
                  /desenvolvedor|programador/i.test(desc);

    if (isDev) {
      job.categoria = 'dev_remoto';
    } else {
      job.categoria = 'ti_geral';
    }
    if (id) staticData.seenJobIds.push(id);
    if (fp) staticData.seenFingerprints.push(fp);
    resultado.push(item);
  }
}

if (staticData.seenJobIds.length > 500) {
  staticData.seenJobIds = staticData.seenJobIds.slice(-500);
}
if (staticData.seenFingerprints.length > 500) {
  staticData.seenFingerprints = staticData.seenFingerprints.slice(-500);
}

return resultado;

